ee:message.ee:set-payload:
%dw 2.0
output application/json
import try from dw::Runtime
import resolve from dw::Timezones

fun parseOffsetMinutes(offset) = do {
    var sign = if (offset[0] == "-") -1 else 1
    var parts = (offset[1 to -1]) splitBy ":"
    var hours = parts[0] as Number
    var mins = parts[1] as Number
    ---
    sign * (hours * 60 + mins)
}

var city1Input = vars.arguments.city1 default ""
var city2Input = vars.arguments.city2 default ""
var tz1 = resolve(city1Input)
var tz2 = resolve(city2Input)

// Wrap in try() so an invalid city/timezone produces a clean -32602 error
// instead of propagating a DataWeave exception to the global handler.
var attempt = try(() -> do {
    var now1 = now() >> (tz1 as TimeZone)
    var now2 = now() >> (tz2 as TimeZone)
    var offset1 = (now1 as String {format: "XXX"})
    var offset2 = (now2 as String {format: "XXX"})
    var mins1 = parseOffsetMinutes(offset1)
    var mins2 = parseOffsetMinutes(offset2)
    var diffMinutes = mins2 - mins1
    var diffHours = diffMinutes / 60
    ---
    if (diffMinutes == 0)
        city1Input ++ " and " ++ city2Input ++ " are in the same timezone"
    else if (diffMinutes > 0)
        city2Input ++ " is " ++ (if (diffHours == floor(diffHours)) (floor(diffHours) as String) else (diffHours as String)) ++ " hours ahead of " ++ city1Input
    else
        city2Input ++ " is " ++ (if ((-diffHours) == floor(-diffHours)) (floor(-diffHours) as String) else ((-diffHours) as String)) ++ " hours behind " ++ city1Input
})
---
if (attempt.success)
{
    "jsonrpc": "2.0",
    "id": vars.requestId,
    "result": {
        "content": [
            {
                "type": "text",
                "text": attempt.result
            }
        ]
    }
}
else
{
    "jsonrpc": "2.0",
    "id": vars.requestId,
    "error": {
        "code": -32602,
        "message": "Invalid city or timezone. Verify 'city1' and 'city2' are supported names or IANA timezone IDs."
    }
}
